-- What if it's asking for count of OWNED households?
SELECT COUNT(*) FROM households 
WHERE LOWER(TRIM(REGEXP_REPLACE(socioeconomic->>'Tenure_Type', '[\t ]+', ' ', 'g'))) = 'owned';

-- What is the count of households with highest income bracket (more than R$ 26,400)?
SELECT COUNT(*) FROM households 
WHERE LOWER(TRIM(REGEXP_REPLACE(socioeconomic->>'Income_Bracket', '[\t ]+', ' ', 'g'))) = 'more than r$ 26,400';
